.forge-section img {max-width:100%}

.forge-section .container {width:min(1200px,90%);margin:0 auto}

.forge-section .section-head {text-align:center;max-width:820px;margin:0 auto 48px}

.forge-section .section-head h2 {font-size:clamp(2rem,4vw,2.9rem)}

.forge-section .section-head p {font-size:1.15rem;color:var(--text);margin-top:16px}

.forge-section {background:var(--surface-subtle)}

.forge-section .logos {display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-top:8px}

.forge-section .logo-item {
  height:88px;background:var(--s2a-color-gray-25, #fff);border:1px solid #eceae7;border-radius:var(--radius-secondary);
  display:flex;align-items:center;justify-content:center;text-align:center;
  font-family:var(--heading-font);font-weight:800;color:var(--gray-600);font-size:15px;padding:12px;transition:.15s;
}

.forge-section .logo-item:hover {color:var(--ink);border-color:#d4d0cb}

.forge-section .center-link {text-align:center;margin-top:36px;font-weight:700}

.forge-section .center-link a::after {content:" \2192"}

.forge-section .quote {
  background:var(--surface);border-radius:var(--radius-primary);
  padding:56px 44px;text-align:center;margin-top:56px;
}

.forge-section .quote .brand {font-family:var(--heading-font);font-weight:800;color:var(--ink);letter-spacing:.03em;margin-bottom:18px;font-size:14px;text-transform:uppercase}

.forge-section .quote h2 {font-size:clamp(1.6rem,3.2vw,2.4rem);max-width:22ch;margin:0 auto 20px}

.forge-section .quote blockquote {font-size:1.25rem;color:var(--text);max-width:48ch;margin:0 auto 18px;font-style:italic}

.forge-section .quote .who {font-weight:700;color:var(--ink)}

.forge-section .quote .read {margin-top:22px;font-weight:700}

.forge-section .quote .read a::after {content:" \2192"}

